  const ready=unsentInvoices.length,overdue=data.invoices.filter(i=>i.termId===termId&&i.lifecycleStatus==="Active"&&i.paymentStatus!=="Paid"&&i.dueDate<today),outstanding=data.invoices.filter(i=>i.termId===termId&&i.lifecycleStatus==="Active"&&i.paymentStatus!=="Paid").reduce((n,i)=>n+i.amountPence,0);
  const trials=data.enrolments.filter(e=>e.termId===termId&&e.status==="Trial").length,missingCoach=data.sessions.filter(s=>!s.coach||s.coach==="Unassigned").length;
