function WeeklyRegisters({programme,data,termId,close,mutate,flash}:{programme:Programme;data:Snapshot;termId:string;close:()=>void;mutate:(a:string,p?:unknown)=>Promise<Snapshot>;flash:(m:string)=>void}){
  const [expanded,setExpanded]=useState<number|null>(null),[working,setWorking]=useState(false);
  const term=data.terms.find(row=>row.id===termId),weeks=data.programmeRegisters.filter(row=>row.programmeId===programme.id&&row.termId===termId).sort((a,b)=>a.weekNumber-b.weekNumber);
  const groupEnrolments=data.enrolments.filter(row=>row.programmeId===programme.id&&row.termId===termId&&row.status!=="Inactive"),players=data.customers.filter(customer=>groupEnrolments.some(row=>row.customerId===customer.id)&&customer.status!=="Inactive");
  const prepare=async()=>{if(working)return;setWorking(true);try{const next=await mutate("prepareProgrammeRegisters",{programmeId:programme.id,termId});const first=next.programmeRegisters.find(row=>row.programmeId===programme.id&&row.termId===termId);setExpanded(first?.id??null);flash(`${term?.sessionCount??0} weekly registers prepared for ${programme.name}`)}catch(error){flash(error instanceof Error?error.message:"Registers could not be prepared")}finally{setWorking(false)}};
  const completed=weeks.filter(row=>row.status==="Complete").length;
  return <Modal title={`${programme.name} weekly registers`} kicker={`${term?.name??"Selected term"} · ${players.length} player${players.length===1?"":"s"}`} close={close}><div className="register-summary"><span><small>Term weeks</small><strong>{weeks.length||term?.sessionCount||0}</strong></span><span><small>Complete</small><strong>{completed}</strong></span><span><small>Remaining</small><strong>{Math.max(0,(weeks.length||term?.sessionCount||0)-completed)}</strong></span></div>{!weeks.length?<div className="prepare-registers"><strong>Prepare the term register</strong><p>This creates one expandable attendance list for every scheduled week. It does not change the schedule or invoices.</p><button className="primary" disabled={working} onClick={()=>void prepare()}>{working?"Preparing weeks…":`Prepare ${term?.sessionCount??0} weekly registers`}</button></div>:<div className="weekly-register-list">{weeks.map(week=><WeeklyRegisterWeek key={week.id} week={week} open={expanded===week.id} toggle={()=>setExpanded(expanded===week.id?null:week.id)} players={players} marks={data.programmeRegisterMarks.filter(mark=>mark.registerId===week.id)} working={working} save={async rows=>{setWorking(true);try{await mutate("saveProgrammeRegister",{registerId:week.id,rows});flash(`Week ${week.weekNumber} register saved`)}catch(error){flash(error instanceof Error?error.message:"Register could not be saved")}finally{setWorking(false)}}}/>)}</div>}<div className="modal-actions"><button className="primary" onClick={close}>Done</button></div></Modal>
}

function WeeklyRegisterWeek({week,open,toggle,players,marks,save,working}:{week:ProgrammeRegister;open:boolean;toggle:()=>void;players:Customer[];marks:ProgrammeRegisterMark[];save:(rows:{playerId:string;mark:string;note:string}[])=>void;working:boolean}){
  const [values,setValues]=useState<Record<string,string>>(Object.fromEntries(players.map(player=>[player.id,marks.find(mark=>mark.playerId===player.id)?.mark??"Present"])));
  useEffect(()=>setValues(Object.fromEntries(players.map(player=>[player.id,marks.find(mark=>mark.playerId===player.id)?.mark??"Present"]))),[marks.length,players.length]);
  const attended=marks.filter(mark=>["Present","Late"].includes(mark.mark)).length;
  return <section className={`weekly-register-week ${week.status==="Complete"?"complete":""}`}><button className="weekly-register-heading" onClick={toggle} aria-expanded={open}><span><b>Week {week.weekNumber}</b><small>{new Date(`${week.sessionDate}T12:00:00Z`).toLocaleDateString("en-GB",{weekday:"short",day:"numeric",month:"short",year:"numeric"})}</small></span><span><em className={`traffic ${week.status==="Complete"?"green":"amber"}`}>{week.status}</em><small>{week.status==="Complete"?`${attended} attended`:"Open to complete"}</small></span><b>{open?"−":"+"}</b></button>{open&&<div className="weekly-register-body">{players.map(player=><div className="weekly-player" key={player.id}><span className="mini-avatar">{player.player.split(" ").map(part=>part[0]).join("")}</span><strong>{player.player}</strong><div className="attendance-buttons">{["Present","Late","Absent","Excused"].map(mark=><button key={mark} type="button" className={values[player.id]===mark?"selected":""} onClick={()=>setValues({...values,[player.id]:mark})}>{mark}</button>)}</div></div>)}{!players.length&&<p className="modal-copy">No active or trial players are registered for this term.</p>}<button className="primary save-week" disabled={working||!players.length} onClick={()=>save(players.map(player=>({playerId:player.id,mark:values[player.id]||"Present",note:""})))}>{working?"Saving…":"Save this week’s register"}</button></div>}</section>
}

function RegisterForm({session,data,close,registerPlayer,save}:{session:Session;data:Snapshot;close:()=>void;registerPlayer:(programme:Programme)=>void;save:(r:Omit<Attendance,"id">[])=>void}){const programme=data.programmes.find(p=>p.name===session.title),registrations=data.enrolments.filter(e=>e.programmeId===programme?.id&&e.termId===session.termId&&e.status!=="Inactive"),ids=registrations.map(e=>e.customerId),players=data.customers.filter(c=>ids.includes(c.id)&&c.status!=="Inactive"),existing=Object.fromEntries(data.attendance.filter(a=>a.sessionId===session.id).map(a=>[a.playerId,a.mark])),[marks,setMarks]=useState<Record<string,string>>(Object.fromEntries(players.map(p=>[p.id,existing[p.id]??"Present"])));return <Modal title={`${session.title} register`} kicker={`${session.sessionDate} · ${session.start}`} close={close}><div className="register-list">{players.map(p=>{const status=registrations.find(e=>e.customerId===p.id)?.status;return <div key={p.id}><span className="mini-avatar">{p.player.split(" ").map(x=>x[0]).join("")}</span><p><strong>{p.player} <em className={`registration-status ${status?.toLowerCase()}`}>{status}</em></strong>{p.medical!=="No medical needs recorded"&&<small className="medical-flag">{p.medical}</small>}</p><div className="attendance-buttons">{["Present","Late","Absent"].map(m=><button key={m} type="button" className={marks[p.id]===m?"selected":""} onClick={()=>setMarks({...marks,[p.id]:m})}>{m}</button>)}</div></div>})}</div>{!players.length&&<p className="modal-copy">No players are registered in this programme for the selected term.</p>}<div className="modal-actions register-actions">{programme&&<button className="secondary" onClick={()=>registerPlayer(programme)}>+ Register player</button>}<button className="secondary" onClick={close}>Cancel</button><button className="primary" disabled={!players.length} onClick={()=>save(players.map(p=>({sessionId:session.id,playerId:p.id,mark:marks[p.id],attendedOn:session.sessionDate})))}>Save register</button></div></Modal>}

